import type { FilterValue } from 'models/Filters';
import { resolveTimePeriodSelection } from 'utils/timePeriod/timePeriodAvailability';

import { getCanonicalVolumeTimePeriodType } from './getCanonicalVolumeTimePeriodType';

interface GetVolumeBigNumberTimePeriodRangeLabelParams {
  cardPeriodType: string | undefined;
  dtEnd: FilterValue | undefined;
  cutoffDate: string | null | undefined;
}

export const getVolumeBigNumberTimePeriodRangeLabel = ({
  cardPeriodType,
  dtEnd,
  cutoffDate,
}: GetVolumeBigNumberTimePeriodRangeLabelParams): string | null => {
  const periodType = getCanonicalVolumeTimePeriodType(cardPeriodType);
  if (!periodType) return null;

  return (
    resolveTimePeriodSelection(periodType, dtEnd, cutoffDate)?.description ??
    null
  );
};
